<script lang="ts">
 import { onMount, tick } from 'svelte';
 import catalog from './wsc2026/catalog.json';
 import SamuraiExample from './wsc2026/SamuraiExample.svelte';
 import SamuraiRules from './wsc2026/SamuraiRules.svelte';
 import round1Playable from './wsc2026/round1Playable.json';
 import { hundredCombinationGroups, primeRunCombinations } from './wsc2026/references.js';
 import { variations } from './variationCatalog';
 import { request, SESSION_KEY, duration, parseTime, playerUrl, readImage } from './wsc2026/client';
 let tab='booklet', round='', search='', error='', notice='', busy=false, session:any=null, sharedPuzzles:any[]=[], token='';
 let username='', restoreKey='';
 let unlocked=false, password='', passwordError='';
 async function unlock(value=password){passwordError='';try{const response=await fetch('/wsc2026/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:value})});if(!response.ok){passwordError=response.status===401?'Incorrect password.':'Unable to unlock the practice room. Try again.';return;}localStorage.setItem('wsc2026-password',value);unlocked=true;password='';const target=new URLSearchParams(location.search).get('returnTo');if(target){const destination=new URL(target,location.origin);if(destination.origin===location.origin&&destination.pathname.startsWith('/wsc2026/')&&!['/wsc2026/','/wsc2026/access'].includes(destination.pathname)){location.replace(destination.href);return;}}await loadLinks();if(token)act('state');}catch{passwordError='Could not unlock. Check your connection and browser storage.';}}
 function officialExampleFor(p:any){const puzzle_url=(round1Playable as Record<string,string>)[p.id];return puzzle_url?[{id:`official:${p.id}`,round:p.round,name:'Official example',source:'official',puzzle_url,booklet_ref:p.id,variant_id:p.variantId}]:[];}
 function practiceFor(p:any){return p.source==='practice'?[p]:[...officialExampleFor(p),...practice.filter((q:any)=>q.booklet_ref?q.booklet_ref===p.id:q.round===p.round&&q.variant_id===p.variantId)];}
 function printEntries(section:any){
  if(section.id!==11)return section.entries;
  const relay=section.entries.find((p:any)=>p.source==='booklet');
  if(!relay)return section.entries;
  return [1,2,3].map(index=>({...relay,id:`${relay.id}-grid-${index}`,name:`Relay example · Grid ${index}`,example:`/wsc2026/relay-example-${index}.png`,relayGrid:index}));
 }
 function printRows(section:any){
  const entries=printEntries(section), perRow=printLandscape&&section.id!==2?2:1;
  return Array.from({length:Math.ceil(entries.length/perRow)},(_,index)=>entries.slice(index*perRow,(index+1)*perRow));
 }
 let title='', addRound='1', variant='classic', puzzleRules='', puzzleUrl='', imageFile:FileList, solutionFile:FileList;
 let devLink='', devPuzzleId=catalog.puzzles[0].id;
 let record:any=null, recordName='', recordTime='', outcome='solved', notes='';
 let printMode='', showAdd=false, showAccount=false, printLandscape=false;
 let openRules:Record<string,boolean>={}, openPuzzles:Record<string,boolean>={};

 $: booklet=catalog.puzzles.map(p=>({...p,source:'booklet'}));
 $: practice=(sharedPuzzles.length?sharedPuzzles:session?.puzzles||[]).map((p:any)=>({...p,id:'practice:'+p.id,round:p.round_id,name:p.title,source:'practice',example:p.image,solution:p.solution_image,points:null,rules:p.rules}));
 $: all=[...booklet,...practice];
 $: cards=[...booklet,...practice.filter((p:any)=>!booklet.some(b=>p.booklet_ref?b.id===p.booklet_ref:b.round===p.round&&b.variantId===p.variant_id))];
 $: filtered=(tab==='plan'?all:cards).filter((p:any)=>(!round||p.round===Number(round))&&(!search||`${p.name} ${p.rules}`.toLowerCase().includes(search.toLowerCase())||practice.some((q:any)=>q.round===p.round&&q.variant_id===p.variantId&&`${q.name} ${q.rules}`.toLowerCase().includes(search.toLowerCase()))));
 $: planned=new Set((session?.plans||[]).filter((p:any)=>p.planned).map((p:any)=>p.puzzle_ref));
 $: roundSections=catalog.rounds.map(r=>({...r,entries:filtered.filter((p:any)=>p.round===r.id)})).filter(r=>r.entries.length);
 $: printable=[...filtered,...(tab==='booklet'?practice.filter((p:any)=>!filtered.some((q:any)=>q.id===p.id)&&(!round||p.round===Number(round))&&(!search||`${p.name} ${p.rules}`.toLowerCase().includes(search.toLowerCase()))):[])].filter((p:any,i:number,items:any[])=>p.source!=='booklet'||items.findIndex(q=>q.source==='booklet'&&q.example===p.example)===i);
 $: printRoundSections=catalog.rounds.map(r=>({...r,entries:printable.filter((p:any)=>p.round===r.id),catalogEntries:filtered.filter((p:any)=>p.round===r.id)})).filter(r=>r.entries.length||r.catalogEntries.length);
 $: selected=filtered.filter((p:any)=>planned.has(p.id));
 $: activeRound=catalog.rounds.find(r=>r.id===Number(round));
 $: attempts=session?.attempts||[];
 $: solved=attempts.filter((a:any)=>a.outcome==='solved');
 async function act(action:string,payload:object={},key=token) {
  busy=true; error=''; notice='';
  try { session=await request(action,key,payload);sharedPuzzles=session.puzzles||sharedPuzzles; token=key; localStorage.setItem(SESSION_KEY,key); localStorage.setItem('wsc2026-username',session.member.username); return true; }
  catch(e:any) { error=e.message; return false; } finally { busy=false; }
 }
 async function loadLinks(){try{const state=await request('links',token||crypto.randomUUID());sharedPuzzles=state.puzzles||[];}catch(e:any){error=e.message;}}
 onMount(()=>{
  try { const saved=localStorage.getItem('wsc2026-password');token=localStorage.getItem(SESSION_KEY)||'';if(saved)unlock(saved); } catch { error='Browser storage is unavailable. Enable localStorage to remember your profile.'; }
  const refresh=()=>{if(unlocked&&token&&session&&!busy)act('state');};
  window.addEventListener('focus',refresh);
  return ()=>{window.removeEventListener('focus',refresh);};
 });
 async function login() { if(await act('join',{username},crypto.randomUUID()))showAccount=false; }
 async function restore() {if(await act('state',{},restoreKey.trim())) {showAccount=false;restoreKey='';}}
 function logout() {notice='';error='';localStorage.removeItem(SESSION_KEY);localStorage.removeItem('wsc2026-username');session=null;token='';showAccount=false;}
 function download(name:string,content:string,type='application/json') {const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function backup() {download('wsc2026-private-backup.json',JSON.stringify({version:1,deviceKey:token,username:session.member.username,group:session.group.name,attempts,plans:session.plans},null,2));notice='Backup downloaded. Keep it private: the device key restores your records on another browser.';}
 async function addPuzzle() {try {const image=await readImage(imageFile?.[0]);const solution_image=await readImage(solutionFile?.[0]);if(!image)throw new Error('Choose a printable puzzle image.');if(puzzleUrl&&!playerUrl(puzzleUrl))throw new Error('Paste a Sudotoku or Penpa puzzle link containing its saved puzzle payload.');if(await act('add_puzzle',{title,round_id:Number(addRound),variant_id:variant,rules:puzzleRules,puzzle_url:puzzleUrl?playerUrl(puzzleUrl):'',image,solution_image})){showAdd=false;title='';puzzleUrl='';puzzleRules='';tab='booklet';notice='Practice puzzle added.';}}catch(e:any){error=e.message;}}
 async function addDevLink(){const link=playerUrl(devLink);if(!link){error='Paste a solver link containing a saved puzzle payload.';return;}busy=true;error='';notice='';try{const state=await request('add_link',token||crypto.randomUUID(),{booklet_ref:devPuzzleId,puzzle_url:link});sharedPuzzles=state.puzzles||[];devLink='';notice='Playable puzzle link added.';}catch(e:any){error=e.message;}finally{busy=false;}}
 function focusModal(node:HTMLElement) {const previous=document.activeElement as HTMLElement;queueMicrotask(()=>node.querySelector<HTMLInputElement>('input')?.focus());const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'){record=null;return;}if(e.key==='Tab'){const els=Array.from(node.querySelectorAll<HTMLElement>('input,select,textarea,button')).filter(el=>!el.hasAttribute('disabled'));const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};node.addEventListener('keydown',handler);return {destroy(){node.removeEventListener('keydown',handler);previous?.focus();}};}
 function openRecord(p:any) {record=p;recordName=session.member.username;recordTime='';outcome='solved';notes='';}
 async function saveRecord(){try{const seconds=parseTime(recordTime);if(await act('record',{puzzle_ref:record.id,round_id:record.round,display_name:recordName,seconds,outcome,notes})){record=null;notice='Private record saved.';}}catch(e:any){error=e.message;}}
 async function plan(p:any){await act('plan',{puzzle_ref:p.id,round_id:p.round,planned:!planned.has(p.id)});}
 async function print(kind:string){printMode=kind;await tick();await Promise.all(Array.from(document.querySelectorAll('.print-area img')).map((img:any)=>img.decode().catch(()=>{})));window.print();printMode='';}
 function csv(){const rows=[['Round','Puzzle','Plan'],...filtered.map((p:any)=>[p.round,p.name,planned.has(p.id)?'Solve':'Skip'])];download('wsc2026-checklist.csv',rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');}
</script>

<svelte:head><title>WSC 2026 · Practice room</title><meta name="description" content="World Sudoku Championship 2026 rules, solved examples, round plans and private practice records."/></svelte:head>
{#if !unlocked}<main class="password-page"><form class="panel" onsubmit={e=>{e.preventDefault();unlock();}}><p class="eyebrow">SUDOTOKU / WSC 2026</p><h1>Practice room</h1><label>Password<input type="password" bind:value={password} required autocomplete="current-password" /></label>{#if passwordError}<p role="alert" class="error">{passwordError}</p>{/if}<button class="primary">Enter</button></form></main>{:else}
<div class="app-shell" inert={!!record}>
 <header><a class="brand" href="/">SUDOTOKU <span>/ TRAINING</span></a><nav><a href="/list/">Variant library ↗</a><button onclick={()=>showAccount=!showAccount}>{session?session.member.username:'Your profile'} <span>↗</span></button></nav></header>
 <main>
  <section class="hero"><div><p class="eyebrow">KOLKATA · 12–13 OCTOBER 2026</p><h1>Prepare with purpose.</h1><p class="intro">Your World Sudoku Championship practice room.<br/>Learn the rules. Plan your rounds. Track your progress.</p></div><div class="event"><span>19TH WORLD</span><strong>SUDOKU<br/>CHAMPIONSHIP</strong><div>2026 <span>INDIA</span></div></div></section>
  <div class="stats"><div><strong>{catalog.puzzles.length}</strong><span>booklet entries</span></div><div><strong>{catalog.rounds.filter(r=>r.available).length}</strong><span>documented rounds</span></div><div><strong>{practice.length}</strong><span>added puzzles</span></div><div><strong>{solved.length}</strong><span>your solved attempts</span></div></div>
  {#if error}<p role="alert" class="message error">{error}</p>{/if}{#if notice}<p role="status" class="message">{notice}</p>{/if}
  {#if showAccount}
   <section class="panel account"><h2>{session?'Your profile':'Choose your username'}</h2>
    {#if session}<p>{session.members.length}/7 members · {session.members.map((m:any)=>m.username).join(', ')}</p><p>Restore your personal device key on another browser to access your private records.</p><div class="actions"><button onclick={backup}>Download private backup</button><button onclick={()=>{notice='Personal device key: '+token;}}>Show my device key</button><button disabled={busy} onclick={logout}>Sign out of this browser</button></div>
    {:else}<form onsubmit={e=>{e.preventDefault();login();}}><div class="form-grid"><label>Username<input bind:value={username} required minlength="2" maxlength="30" placeholder="Your username"/></label></div><button class="primary" disabled={busy}>Continue</button></form><details><summary>Already registered? Restore on this browser</summary><form onsubmit={e=>{e.preventDefault();restore();}}><label>Personal device key<input bind:value={restoreKey} required placeholder="Key from your private backup"/></label><button disabled={busy}>Restore my profile</button></form></details><p class="small">No email or password. A private device key protects your records. Download a backup after joining; a username alone cannot recover an existing profile.</p>{/if}
   </section>
  {/if}
  <div class="tabs" role="tablist" aria-label="Practice sections">{#each [['booklet','Rules & examples'],['plan','My round plan'],['records','My records'],['dev','Add puzzle']] as item}<button role="tab" aria-selected={tab===item[0]} class:active={tab===item[0]} onclick={()=>tab=item[0]}>{item[1]}</button>{/each}</div>
  {#if ['booklet','plan'].includes(tab)}
   <section class="toolbar"><label>Round<select aria-label="Round" bind:value={round}><option value="">All rounds</option>{#each catalog.rounds as r}<option value={String(r.id)}>{String(r.id).padStart(2,'0')} · {r.name}</option>{/each}</select></label><label class="search">Find a puzzle<input bind:value={search} type="search" placeholder="Search names or rules…"/></label><fieldset class="layout-picker"><legend>PDF layout</legend><button type="button" aria-label="Portrait · one puzzle per page" aria-pressed={!printLandscape} class:active={!printLandscape} onclick={()=>printLandscape=false}><span class="page-icon portrait-icon"><b>1</b></span><span>Portrait</span></button><button type="button" aria-label="Landscape · two puzzles per page" aria-pressed={printLandscape} class:active={printLandscape} onclick={()=>printLandscape=true}><span class="page-icon landscape-icon"><b>1</b><b>2</b></span><span>Landscape</span></button></fieldset><div class="actions"><button onclick={()=>print(tab==='plan'?'plan':'puzzles')}>Print / Save PDF</button>{#if tab==='plan'}<button onclick={csv}>Download checklist</button>{/if}{#if tab==='booklet'&&session}<button class="primary" onclick={()=>showAdd=!showAdd}>+ Add puzzle</button>{/if}</div></section>
   {#if tab==='booklet'}<p class="source">Instruction booklet v1 · 16 September 2026. Team round puzzle sections are absent from this file. <a href="https://wspc2026.logicmastersindia.com/?g=WSC" target="_blank" rel="noreferrer">Open original instruction booklet ↗</a></p>{/if}
   {#if !session&&tab!=='booklet'}<section class="empty"><h2>Your practice starts here.</h2><p>Set up your profile to add puzzles, save private times and plan your rounds across devices.</p><button class="primary" onclick={()=>showAccount=true}>Set up my profile</button></section>{/if}
   {#if showAdd&&session&&tab==='booklet'}<form class="panel" onsubmit={e=>{e.preventDefault();addPuzzle();}}><h2>Add a practice puzzle</h2><div class="form-grid"><label>Title<input bind:value={title} required maxlength="160"/></label><label>Round<select bind:value={addRound}>{#each catalog.rounds as r}<option value={String(r.id)}>{r.id} · {r.name}</option>{/each}</select></label><label>Variant<select aria-label="Variant" bind:value={variant}>{#each variations as v}<option value={v.value}>{v.name}</option>{/each}</select></label><label>Sudotoku puzzle link (optional)<input bind:value={puzzleUrl} type="url" placeholder="https://…"/></label><label>Puzzle image · up to 3 MB<input type="file" bind:files={imageFile} accept="image/png,image/jpeg,image/webp" required/></label><label>Solution image (optional)<input type="file" bind:files={solutionFile} accept="image/png,image/jpeg,image/webp"/></label></div><label>Rules<textarea bind:value={puzzleRules} maxlength="10000" rows="3"></textarea></label><button class="primary" disabled={busy}>Save puzzle</button></form>{/if}
   {#if tab==='plan'}<div class="plan-summary"><strong>{selected.length} planned in this view</strong><span>{selected.reduce((sum:number,p:any)=>sum+(p.points||0),0)} booklet points selected</span></div>{/if}
   {#each roundSections as section (section.id)}<section class="round-section"><div class="round-heading"><h2>{String(section.id).padStart(2,'0')} / {section.name}</h2><p>{section.minutes ? section.minutes+' minutes · '+section.points+' points' : 'Team round'}</p></div><div class="puzzle-list">{#each section.entries as p (p.id)}<article class="puzzle-card" class:clickable-card={p.variantId!=='classic'||p.source!=='booklet'} onclick={(e)=>{if((e.target as Element).closest('.samurai-example'))return;if(p.variantId!=='classic'||p.source!=='booklet')openRules={...openRules,[p.id]:!openRules[p.id]};}}><div class="card-heading"><h2>{p.name}</h2>{#if p.points}<span class="points">{p.points} <small>PTS</small></span>{/if}</div>
    <div class="card-controls"><p class="eyebrow">{p.number?'#'+p.number:'PRACTICE'} · {section.name}{p.stage?' · '+p.stage:''}</p><div class="actions">{#if p.variantId==='star'}<a href="/solver/star/" onclick={e=>e.stopPropagation()}>Open Star solver ↗</a>{/if}{#if tab!=='plan'&&practiceFor(p).length}<button aria-expanded={!!openPuzzles[p.id]} aria-controls={'puzzles-'+p.id} onclick={(e)=>{e.stopPropagation();openPuzzles={...openPuzzles,[p.id]:!openPuzzles[p.id]};}}>Puzzles ({practiceFor(p).length}) {openPuzzles[p.id]?'▴':'▾'}</button>{/if}{#if session}<button class:chosen={planned.has(p.id)} aria-pressed={planned.has(p.id)} disabled={busy} onclick={(e)=>{e.stopPropagation();plan(p);}}>{planned.has(p.id)?'✓ Planned':'+ Plan'}</button><button onclick={(e)=>{e.stopPropagation();openRecord(p);}}>Record time</button>{/if}</div></div>
    {#if p.variantId!=='classic' || p.source!=='booklet'}<div id={'rules-'+p.id} hidden={!openRules[p.id]} class="card-expanded"><p class="rules" hidden={p.round===2&&p.source==='booklet'}>{p.rules}</p>{#if p.round===3}<details class="number-reference" onclick={e=>e.stopPropagation()}><summary>All 100-sum combinations ({hundredCombinationGroups.reduce((total,group)=>total+group.combinations.length,0)})</summary><p>Every grouping that fits in a 9-cell row is included. Addends may appear in any order; digits cannot repeat within the row. For each pattern, look up either digit of a 2-digit number to find its possible partner. Each pair occurs in at least one full combination; multiple pairs cannot necessarily be combined freely.</p>{#each hundredCombinationGroups as group}<details class="hundred-group"><summary>{group.label} ({group.combinations.length})</summary><div class="hundred-lookups">
 <table><caption>Given the tens digit</caption><thead><tr><th scope="col">Tens</th><th scope="col">Possible units</th></tr></thead><tbody>{#each group.byTens as entry}<tr><th scope="row">{entry.digit}</th><td>{entry.possibleDigits.length?entry.possibleDigits.join(', '):'None'}</td></tr>{/each}</tbody></table>
 <table><caption>Given the units digit</caption><thead><tr><th scope="col">Units</th><th scope="col">Possible tens</th></tr></thead><tbody>{#each group.byUnits as entry}<tr><th scope="row">{entry.digit}</th><td>{entry.possibleDigits.length?entry.possibleDigits.join(', '):'None'}</td></tr>{/each}</tbody></table>
 </div><details><summary>Full combinations ({group.combinations.length})</summary><div class="number-chips">{#each group.combinations as combination}<code>{combination}</code>{/each}</div></details></details>{/each}</details>{/if}{#if p.id==='r06-08'}<details class="number-reference" onclick={e=>e.stopPropagation()}><summary>All possible Prime Run sums ({primeRunCombinations.length})</summary><div class="prime-sum-groups">{#each primeRunCombinations as entry}<div><strong>{entry.sum}</strong><span>{#each entry.digitSets as digits}<code>{digits.join(' + ')}</code>{/each}</span></div>{/each}</div><p>Each row shows a sum followed by every non-empty set of the prime Sudoku digits 2, 3, 5 and 7 that produces it.</p></details>{/if}{#if p.source==='booklet'}{#if p.round===2}<SamuraiExample example={p.example} solution={p.solution}/>{:else}<img class="official" src={p.image} alt={p.name+': official example and solution'} loading="lazy"/>{/if}{/if}</div>{/if}
    {#if tab!=='plan' && practiceFor(p).length}<div id={'puzzles-'+p.id} hidden={!openPuzzles[p.id]} class="puzzle-entries card-expanded">{#each practiceFor(p) as q,i}<div class="practice-entry">{#if q.puzzle_url&&playerUrl(q.puzzle_url)}<a href={playerUrl(q.puzzle_url)} target="_blank" rel="noopener noreferrer">{i+1}. {q.name} ↗</a>{:else}<details><summary>{i+1}. {q.name}</summary><img src={q.example} alt={q.name} loading="lazy"/>{#if q.solution}<details><summary>Reveal solution</summary><img src={q.solution} alt={q.name+' solution'} loading="lazy"/></details>{/if}</details>{/if}{#if session}<button onclick={()=>openRecord(q)}>Record time</button>{/if}</div>{/each}</div>{/if}
</article>{/each}</div></section>{/each}
   {#if filtered.length===0&&session}<section class="empty"><h2>No puzzles in this view.</h2><p>{activeRound&&!activeRound.available?'This team round has no puzzle details in the supplied file. You can still add your own practice puzzles.':'Try a different filter or add a practice puzzle.'}</p></section>{/if}
  {:else if tab==='dev'}
   <section class="panel dev-panel"><h2>Add a playable puzzle</h2><p>Paste the link copied from the solver, then attach it to its WSC variant.</p><form onsubmit={e=>{e.preventDefault();addDevLink();}}><label>Link<input bind:value={devLink} type="url" required placeholder="https://…/#p=…"/></label><label>Variant name<select bind:value={devPuzzleId} required>{#each catalog.rounds as r}{#if catalog.puzzles.some(p=>p.round===r.id)}<optgroup label={`Round ${String(r.id).padStart(2,'0')} · ${r.name}`}>{#each catalog.puzzles.filter(p=>p.round===r.id) as p}<option value={p.id}>#{p.number} · {p.name}</option>{/each}</optgroup>{/if}{/each}</select></label><button class="primary" disabled={busy}>Add puzzle</button></form></section>
  {:else if tab==='records'}
   <section class="section-heading"><h2>Your private training log</h2><p>Only your profile can read these records. Times are self-reported.</p>{#if session}<button onclick={backup}>Download records & backup</button>{/if}</section><div class="records">{#each attempts as a}<article><div><strong>{all.find((p:any)=>p.id===a.puzzle_ref)?.name||a.puzzle_ref}</strong><p>{a.display_name} · {new Date(a.solved_at).toLocaleString()} · {a.outcome}</p>{#if a.notes}<p>{a.notes}</p>{/if}</div><strong>{duration(a.seconds)}</strong><button disabled={busy} onclick={()=>act('delete_attempt',{id:a.id})}>Delete</button></article>{:else}<p class="empty">No records yet. Use “Record time” after a solve.</p>{/each}</div>
  {/if}
 </main><footer>Examples © WSC 2026 organizing team and credited authors. Non-commercial practice only. <a href="https://wspc2026.logicmastersindia.com/?g=WSC" target="_blank" rel="noreferrer">Official WSC 2026 booklet</a></footer>
</div>
{#if record}<div class="modal-backdrop"><div class="modal" use:focusModal role="dialog" tabindex="-1" aria-modal="true" aria-labelledby="record-title"><h2 id="record-title">Record your solve</h2><p>{record.name}</p><form onsubmit={e=>{e.preventDefault();saveRecord();}}><label>Name<input bind:value={recordName} required maxlength="80"/></label><label>Time (minutes:seconds)<input bind:value={recordTime} required placeholder="12:34" /></label><label>Result<select bind:value={outcome}><option value="solved">Solved correctly</option><option value="dnf">Did not finish</option><option value="error">Finished with an error</option></select></label><label>Notes<textarea bind:value={notes} maxlength="2000" placeholder="What slowed you down?"></textarea></label>{#if error}<p role="alert" class="error">{error}</p>{/if}<div class="actions"><button class="primary" disabled={busy}>Save privately</button><button type="button" onclick={()=>record=null}>Cancel</button></div></form></div></div>{/if}
{#if printMode}<section class:landscape={printLandscape} class="print-area"><div class="pack-cover"><h1>WSC 2026 · {printMode==='plan'?'Round checklist':'Practice pack'}</h1><p>{activeRound?`Round ${activeRound.id}: ${activeRound.name}`:'All rounds'} · {new Date().toLocaleDateString()}</p></div>{#if printMode==='plan'}<table><thead><tr><th>Plan</th><th>Round</th><th>Puzzle</th><th>Points</th><th>Time / notes</th></tr></thead><tbody>{#each filtered as p}<tr><td>{planned.has(p.id)?'☑':'☐'}</td><td>{p.round}</td><td>{p.name}</td><td>{p.points||'—'}</td><td>________________</td></tr>{/each}</tbody></table>{:else}{#each printRoundSections as section}<article class="round-preview"><p class="eyebrow">ROUND {String(section.id).padStart(2,'0')}</p><h2>{section.name}</h2><p class="round-meta">{section.minutes ? section.minutes+' minutes · '+section.points+' points' : 'Team round'}</p><h3>Puzzle order</h3><ol>{#each section.catalogEntries as p}<li><span>#{p.number} · {p.name}</span><strong>{p.points||'—'} pts</strong></li>{/each}</ol>{#if section.id===2}<SamuraiRules/>{/if}</article><div class="print-puzzle-grid" class:round-two={section.id===2} class:round-eleven={section.id===11}>{#each printRows(section) as row}<div class="print-puzzle-row" class:samurai-row={section.id===2}>{#each row as p}<article class="print-puzzle" class:samurai={section.id===2} class:relay-grid={section.id===11}><div class="print-puzzle-heading"><h2>#{p.round}.{p.number||'P'} · {p.name} · {p.points||'—'} pts</h2><div class="time-box">TIME<span>____ : ____</span></div></div>{#if p.variantId!=='classic' || p.source!=='booklet'}<p>{p.rules}</p>{/if}{#if p.round===2&&p.source==='booklet'}<p class="samurai-print-key">Top left: No Three in a Line · Top right: Creasing<br/>Centre: Palindrome · Bottom left & right: Clone Along Line</p>{/if}{#if p.example}<img src={p.example} alt={p.name}/>{:else}<p>This composite example is available in the original booklet, PDF page {p.page}.</p>{/if}</article>{/each}</div>{/each}</div>{/each}{/if}<p class="small print-credit">WSC 2026 instruction booklet v1. Examples for non-commercial practice; rights remain with credited authors.</p></section>{/if}

